/**
 * Canonical 8-4-4-4-12 hex UUID format regex matching UUIDs generated by PostgreSQL / Prisma / crypto.randomUUID().
 * Form: 8 hex - 4 hex - 4 hex - 4 hex - 12 hex (total 36 characters including hyphens).
 *
 * NOTE: Validates canonical hyphenated hex layout; does not constrain RFC-4122 version or variant bits.
 */
export const CANONICAL_UUID_REGEX =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Validates whether a value is a string conforming strictly and exactly to the
 * canonical 8-4-4-4-12 hex UUID format.
 *
 * Strict validation rules:
 * - No trimming or implicit normalization.
 * - Leading, trailing, or internal whitespace is strictly rejected.
 * - Validates the exact representation that will be used in JWT payloads and database queries.
 */
export function isCanonicalUuid(value: unknown): value is string {
  return typeof value === "string" && CANONICAL_UUID_REGEX.test(value);
}

